window.addEventListener('load', () => {
  document.querySelectorAll('.bar').forEach(b => { b.style.width = b.dataset.w; });
  setTimeout(()=>document.querySelectorAll('svg.chart rect[data-w]').forEach(r=>r.setAttribute('width', r.dataset.w)),300);
});
document.querySelectorAll('.ctab').forEach(b=>b.addEventListener('click',()=>{
  document.querySelectorAll('.ctab').forEach(x=>x.classList.remove('on')); b.classList.add('on');
  document.querySelectorAll('.case').forEach(c=>c.classList.toggle('on', c.id==='case-'+b.dataset.c)); dispatchEvent(new Event('resize'));
  document.querySelectorAll('svg.chart rect[data-w]').forEach(r=>r.setAttribute('width', r.dataset.w));
}));

