/* ===== AEROSPACE: sealed Airbus sweep + nonlinearity ===== */
(function(){
  const C=canvasCtx('cvA'); let t0=performance.now(); let raf=null;
  const logy=(v,ymin,ymax,T,B)=>B-(Math.log10(v)-ymin)/(ymax-ymin)*(B-T);
  function sweep(){
    const {ctx,rect}=C; C.resize(); ctx.clearRect(0,0,rect.width,rect.height);
    const t=(performance.now()-t0)/1000, frac=Math.min(1,t/2.2);
    const L=64,R=rect.width-24,T=30,B=rect.height-60;
    const x0=1,x1=Math.log10(102400);
    const X=re=>L+(Math.log10(re)-x0)/(x1-x0)*(R-L);
    const ymin=-15,ymax=-1;
    ctx.strokeStyle='#D9DBD6'; ctx.strokeRect(L,T,R-L,B-T);
    ctx.font=MONO; ctx.fillStyle='#5A5D58'; ctx.textAlign='left';
    [-3,-7,-11,-15].forEach(e=>{const y=logy(Math.pow(10,e),ymin,ymax,T,B); ctx.fillText('1e'+e, 8, y+3); ctx.strokeStyle='#ECEEE8'; ctx.beginPath(); ctx.moveTo(L,y); ctx.lineTo(R,y); ctx.stroke();});
    ctx.textAlign='center'; AER.serie.forEach(p=>ctx.fillText(p.Re>=1000?(p.Re/1000)+'k':p.Re, X(p.Re), B+16));
    ctx.fillText('Reynolds number →', (L+R)/2, B+34);
    const m=Math.max(2,Math.ceil(AER.serie.length*frac));
    const line=(key,col,w)=>{ctx.strokeStyle=col;ctx.lineWidth=w;ctx.beginPath();let started=false;
      for(let i=0;i<m;i++){const p=AER.serie[i]; if(p[key]==null) continue; const x=X(p.Re),y=logy(p[key],ymin,ymax,T,B); if(!started){ctx.moveTo(x,y);started=true;} else ctx.lineTo(x,y);} ctx.stroke();
      for(let i=0;i<m;i++){const p=AER.serie[i]; if(p[key]==null) continue; ctx.beginPath();ctx.arc(X(p.Re),logy(p[key],ymin,ymax,T,B),3,0,7);ctx.fillStyle=col;ctx.fill();}};
    line('fd',INK,2); line('sp',TEAL,2);
    ctx.strokeStyle=RED; ctx.lineWidth=2.2; ctx.beginPath(); let st=false;
    for(let i=0;i<m;i++){const p=AER.serie[i]; if(p.k1==null) break; const x=X(p.Re),y=logy(p.k1,ymin,ymax,T,B); if(!st){ctx.moveTo(x,y);st=true;} else ctx.lineTo(x,y);}
    ctx.stroke();
    for(let i=0;i<m;i++){const p=AER.serie[i]; if(p.k1==null){
        const x=X(p.Re); ctx.strokeStyle=RED; ctx.lineWidth=1.4; ctx.setLineDash([3,3]); ctx.beginPath(); ctx.moveTo(x,T); ctx.lineTo(x,B); ctx.stroke(); ctx.setLineDash([]);
        ctx.fillStyle=RED; ctx.save(); ctx.translate(x-4, T+70); ctx.rotate(-Math.PI/2); ctx.textAlign='center'; ctx.fillText(p.k1q+'q needed · cap 12', 0, 0); ctx.restore();
      } else {ctx.beginPath();ctx.arc(X(p.Re),logy(p.k1,ymin,ymax,T,B),3,0,7);ctx.fillStyle=RED;ctx.fill();}}
    ctx.textAlign='left'; ctx.fillStyle=TEAL; ctx.fillText('spectral (classical champion) → machine zero', L+8, T+14);
    ctx.fillStyle=INK; ctx.fillText('finite differences: error falls 4 orders', L+8, T+28);
    ctx.fillStyle=RED; ctx.fillText('quantum (Carleman K1): 3 of 8 solved, error 28–89× classical · K2: 0 of 8', L+8, T+42);
    if(frac<1) raf=requestAnimationFrame(sweep);
  }
  function nolin(){
    const {ctx,rect}=C; C.resize(); ctx.clearRect(0,0,rect.width,rect.height);
    const t=(performance.now()-t0)/1000;
    const L=64,R=rect.width-24,T=30,B=rect.height-60; const n=AER.nolin.length;
    const ymin=-17,ymax=0;
    ctx.strokeStyle='#D9DBD6'; ctx.strokeRect(L,T,R-L,B-T);
    ctx.font=MONO; ctx.fillStyle='#5A5D58'; ctx.textAlign='left';
    [0,-4,-8,-12,-16].forEach(e=>{const y=logy(Math.pow(10,e),ymin,ymax,T,B); ctx.fillText('1e'+e, 8, y+3); ctx.strokeStyle='#ECEEE8'; ctx.beginPath(); ctx.moveTo(L,y); ctx.lineTo(R,y); ctx.stroke();});
    const bw=(R-L)/n;
    const m=Math.min(n,Math.floor(t*9)+1);
    for(let i=0;i<m;i++){const v=AER.nolin[i]; const x=L+i*bw+bw/2; const y=logy(Math.max(v.r,1e-17),ymin,ymax,T,B);
      const zero=v.r<1e-10;
      ctx.strokeStyle=zero?RED:'#9A9D98'; ctx.lineWidth=Math.min(10,bw*0.5); ctx.beginPath(); ctx.moveTo(x,B); ctx.lineTo(x,y); ctx.stroke();
      if(zero){ctx.fillStyle=RED; ctx.beginPath(); ctx.arc(x,y,3.4,0,7); ctx.fill();}}
    const yc=logy(AER.ctrl,ymin,ymax,T,B);
    ctx.strokeStyle=TEAL; ctx.lineWidth=1.6; ctx.setLineDash([5,3]); ctx.beginPath(); ctx.moveTo(L,yc); ctx.lineTo(R,yc); ctx.stroke(); ctx.setLineDash([]);
    ctx.fillStyle=TEAL; ctx.textAlign='right'; ctx.fillText('random band-limited field: 0.29 — the term is real elsewhere', R-6, yc-6);
    ctx.textAlign='left'; ctx.fillStyle=INK; ctx.fillText('nonlinear-to-linear ratio per variant · 18 variants of the statement vortex', L+8, T+14);
    ctx.fillStyle=RED; ctx.fillText('5 variants: the term vanishes at machine zero (1e-16) — 11.6 orders below the rest', L+8, T+28);
    ctx.fillStyle='#5A5D58'; ctx.textAlign='center'; ctx.fillText('variants →', (L+R)/2, B+16);
    if(m<n) raf=requestAnimationFrame(nolin);
  }
  function run(){ if(raf) cancelAnimationFrame(raf); t0=performance.now(); (PANEL_MODE.aero==='nolin'?nolin:sweep)(); }
  window.restart_aero=run; run();
  document.querySelector('.ctab[data-c="aero"]').addEventListener('click',()=>setTimeout(run,30));
})();

/* ===== BANKING: real sealed scores ===== */
(function(){
  const C=canvasCtx('cvB'); let t0=performance.now(); let raf=null;
  function cloud(){
    const {ctx,rect}=C; C.resize(); ctx.clearRect(0,0,rect.width,rect.height);
    const t=(performance.now()-t0)/1000; const L=54,R=rect.width-20,T=26,B=rect.height-44;
    const X=v=>L+v*(R-L), Y=v=>B-v*(B-T);
    ctx.strokeStyle='#D9DBD6'; ctx.strokeRect(L,T,R-L,B-T);
    ctx.font=MONO; ctx.fillStyle='#5A5D58'; ctx.textAlign='center'; ctx.fillText('quantum kernel score (rank) →', (L+R)/2, rect.height-10);
    ctx.save(); ctx.translate(14,(T+B)/2); ctx.rotate(-Math.PI/2); ctx.fillText('classical score (rank) →',0,0); ctx.restore();
    ctx.textAlign='left'; ctx.fillText('a perfect detector puts every fraud in the top-right corner', L+6, T+14);
    const n=BANK.pts.length; const shown=Math.min(n, Math.floor(t*1400));
    for(let i=0;i<shown;i++){const [q,c,f]=BANK.pts[i]; if(f) continue; ctx.fillStyle='rgba(22,24,27,0.16)'; ctx.fillRect(X(q)-1,Y(c)-1,2,2);}
    for(let i=0;i<shown;i++){const [q,c,f]=BANK.pts[i]; if(!f) continue; ctx.beginPath(); ctx.arc(X(q),Y(c),4,0,7); ctx.fillStyle=RED; ctx.fill();}
    if(shown>=n){ ctx.fillStyle=RED; ctx.textAlign='right'; ctx.fillText('frauds: high on the classical axis, scattered on the quantum one', R-6, B-8); }
    if(shown<n) raf=requestAnimationFrame(cloud);
  }
  function pr(){
    const {ctx,rect}=C; C.resize(); ctx.clearRect(0,0,rect.width,rect.height);
    const t=(performance.now()-t0)/1000; const L=54,R=rect.width-20,T=26,B=rect.height-44;
    const X=v=>L+v*(R-L), Y=v=>B-v*(B-T);
    ctx.strokeStyle='#D9DBD6'; ctx.strokeRect(L,T,R-L,B-T);
    ctx.font=MONO; ctx.fillStyle='#5A5D58'; ctx.textAlign='center'; ctx.fillText('recall →', (L+R)/2, rect.height-10);
    ctx.save(); ctx.translate(14,(T+B)/2); ctx.rotate(-Math.PI/2); ctx.fillText('precision →',0,0); ctx.restore();
    const frac=Math.min(1,t/2.5);
    const line=(pts,col,w)=>{ctx.strokeStyle=col;ctx.lineWidth=w;ctx.beginPath();const m=Math.max(2,Math.floor(pts.length*frac));for(let i=0;i<m;i++){const [r,p]=pts[i]; if(i===0)ctx.moveTo(X(r),Y(p)); else ctx.lineTo(X(r),Y(p));}ctx.stroke();};
    line(BANK.pr_c, INK, 2); line(BANK.pr_q, RED, 2.2);
    ctx.textAlign='left'; ctx.fillStyle=RED; ctx.fillText('quantum kernel · AUPRC 0.257 (sealed)', L+8, T+16);
    ctx.fillStyle=INK; ctx.fillText('classical baseline · XGBoost · AUPRC 0.801 (sealed)', L+8, T+32);
    if(frac<1) raf=requestAnimationFrame(pr);
  }
  function run(){ if(raf) cancelAnimationFrame(raf); t0=performance.now(); (PANEL_MODE.bank==='pr'?pr:cloud)(); }
  window.restart_bank=run; run();
  document.querySelector('.ctab[data-c="banking"]').addEventListener('click',()=>setTimeout(run,30));
})();

