const hsI=document.getElementById('hsInput'), hsR=document.getElementById('hsResults');
function hsRender(q){
  const ql=q.trim().toLowerCase();
  const hits=ql? HS_INDEX.filter(e=>e.t.toLowerCase().includes(ql)||e.st.toLowerCase().includes(ql)) : [];
  hsR.innerHTML = hits.length ? hits.map(e=>`<div class="hs-r"><span>${e.t}</span><span class="st" style="color:${e.c}">${e.st}</span></div>`).join('')
    : (ql?`<div class="hs-r"><span>No match in the quick index — open the full Library search</span><span class="st">/library →</span></div>`:'');
  hsR.classList.toggle('on', !!ql);
}
hsI.addEventListener('input',e=>hsRender(e.target.value));
document.getElementById('hsBtn').addEventListener('click',()=>hsRender(hsI.value));
document.querySelectorAll('.hs-chip').forEach(ch=>ch.addEventListener('click',()=>{hsI.value=ch.textContent; hsRender(ch.textContent); hsI.focus();}));
document.addEventListener('click',e=>{if(!e.target.closest('.lh-search') && !e.target.closest('.hs-chip')) hsR.classList.remove('on');});
document.querySelectorAll('.vtog').forEach(v=>v.addEventListener('click',()=>{const w=v.nextElementSibling; const on=w.classList.toggle('on'); v.textContent = on ? 'hide ↙' : 'verify ↗';}));
const mm2=document.getElementById('monMail'), mg=document.getElementById('monGo');
if(mm2&&mg){mm2.addEventListener('input',()=>{mg.href='mailto:hello@rosettaquantum.com?subject=Send%20me%20Monitor%20Edition%20001&body='+encodeURIComponent(mm2.value);});}
/* Nav: scroll por JS (los visores embebidos bloquean la navegación por #hash) */
document.querySelectorAll('a[href^="#"]').forEach(a=>{
  a.addEventListener('click',e=>{
    const id=a.getAttribute('href').slice(1); const el=id&&document.getElementById(id);
    if(el){e.preventDefault(); const y=el.getBoundingClientRect().top+window.scrollY-64; window.scrollTo({top:y,behavior:'smooth'});
      document.querySelectorAll('.nav-links a').forEach(x=>x.classList.toggle('on',x===a));}
  });
});
