/* ===== caminata.js — copia fiel del motor del hero 3D (rama cleveland-hero-oficial) =====
   Caminata cuántica de tiempo continuo: i·dψ/dt = Hψ, RK4, H = adyacencia ponderada gaussiana. */
// Caminata cuántica de tiempo continuo sobre la red de contactos.
//
// TODO ESTO SE CALCULA EN EL NAVEGADOR. Lo único que viene sellado son las coordenadas
// y los parámetros de la red (corte y sigma), que se leen de /v1/structures — no se
// recuerdan. Al terminar de armarse, la caminata se contrasta contra el valor sellado:
// si el ranking no coincide, se dice, no se maquilla.

function parametrosDeRed(estructura) {
  const corte = estructura?.red?.corte_angstrom;
  const m = /sigma\s*=\s*([0-9.]+)/i.exec(estructura?.red?.peso || '');
  if (typeof corte !== 'number' || !m) return null;      // sin parámetros no se inventa
  return { corte, sigma: parseFloat(m[1]), texto: estructura.red.peso };
}

// Lista de adyacencia con peso gaussiano, tal como la declara la receta.
function construirRed(coords, { corte, sigma }) {
  const n = coords.length;
  const vec = Array.from({ length: n }, () => []);
  const c2 = corte * corte, dos2 = 2 * sigma * sigma;
  for (let i = 0; i < n; i++) {
    const [xi, yi, zi] = coords[i];
    for (let j = i + 1; j < n; j++) {
      const [xj, yj, zj] = coords[j];
      const d2 = (xi-xj)**2 + (yi-yj)**2 + (zi-zj)**2;
      if (d2 > c2) continue;
      const w = Math.exp(-d2 / dos2);
      vec[i].push([j, w]); vec[j].push([i, w]);
    }
  }
  const grado = vec.map(l => l.reduce((s, [, w]) => s + w, 0));
  return { n, vec, grado };
}

// y = H x, con H = A (adyacencia) o H = L (laplaciano D − A)
function porH(red, xr, xi, yr, yi, laplaciano) {
  const { n, vec, grado } = red;
  for (let i = 0; i < n; i++) {
    let sr = 0, si = 0;
    const l = vec[i];
    for (let k = 0; k < l.length; k++) { const [j, w] = l[k]; sr += w * xr[j]; si += w * xi[j]; }
    if (laplaciano) { yr[i] = grado[i]*xr[i] - sr; yi[i] = grado[i]*xi[i] - si; }
    else { yr[i] = sr; yi[i] = si; }
  }
}

function nuevoEstado(red, fuente) {
  const { n } = red;
  const psiR = new Float64Array(n), psiI = new Float64Array(n);
  const a = 1 / Math.sqrt(fuente.length);
  fuente.forEach(i => { psiR[i] = a; });
  return { psiR, psiI, t: 0, tmp: Array.from({ length: 8 }, () => new Float64Array(n)) };
}

// Un paso de Runge-Kutta 4 sobre i·dψ/dt = Hψ  →  dψ/dt = −i·Hψ
function paso(red, est, dt, laplaciano) {
  const { n } = red, { psiR, psiI, tmp } = est;
  const [k1r,k1i,k2r,k2i,k3r,k3i,ar,ai] = tmp;
  const deriv = (xr, xi, or_, oi) => {           // −i H x  =  (H x)_i·(−i)
    porH(red, xr, xi, or_, oi, laplaciano);
    for (let i = 0; i < n; i++) { const re = or_[i], im = oi[i]; or_[i] = im; oi[i] = -re; }
  };
  deriv(psiR, psiI, k1r, k1i);
  for (let i = 0; i < n; i++) { ar[i] = psiR[i] + dt/2*k1r[i]; ai[i] = psiI[i] + dt/2*k1i[i]; }
  deriv(ar, ai, k2r, k2i);
  for (let i = 0; i < n; i++) { ar[i] = psiR[i] + dt/2*k2r[i]; ai[i] = psiI[i] + dt/2*k2i[i]; }
  deriv(ar, ai, k3r, k3i);
  for (let i = 0; i < n; i++) { ar[i] = psiR[i] + dt*k3r[i]; ai[i] = psiI[i] + dt*k3i[i]; }
  const [k4r, k4i] = [new Float64Array(n), new Float64Array(n)];
  deriv(ar, ai, k4r, k4i);
  for (let i = 0; i < n; i++) {
    psiR[i] += dt/6*(k1r[i] + 2*k2r[i] + 2*k3r[i] + k4r[i]);
    psiI[i] += dt/6*(k1i[i] + 2*k2i[i] + 2*k3i[i] + k4i[i]);
  }
  est.t += dt;
}

function probabilidad(est, salida) {
  const { psiR, psiI } = est;
  for (let i = 0; i < psiR.length; i++) salida[i] = psiR[i]*psiR[i] + psiI[i]*psiI[i];
  return salida;
}

// Promedio temporal sobre la ventana declarada por la receta.
function promedioEnVentana(red, fuente, [t0, t1], laplaciano, dt = 0.01) {
  const est = nuevoEstado(red, fuente);
  const acc = new Float64Array(red.n), p = new Float64Array(red.n);
  let muestras = 0;
  while (est.t < t1) {
    paso(red, est, dt, laplaciano);
    if (est.t >= t0) { probabilidad(est, p); for (let i = 0; i < red.n; i++) acc[i] += p[i]; muestras++; }
  }
  for (let i = 0; i < red.n; i++) acc[i] /= muestras || 1;
  return acc;
}

function spearman(a, b) {
  const rango = (v) => {
    const o = Array.from(v, (x, i) => [x, i]).sort((p, q) => p[0]-q[0]);
    const r = new Float64Array(v.length);
    o.forEach(([, i], k) => { r[i] = k; });
    return r;
  };
  const ra = rango(a), rb = rango(b), n = a.length;
  let ma = 0, mb = 0;
  for (let i = 0; i < n; i++) { ma += ra[i]; mb += rb[i]; }
  ma /= n; mb /= n;
  let num = 0, da = 0, db = 0;
  for (let i = 0; i < n; i++) {
    const x = ra[i]-ma, y = rb[i]-mb;
    num += x*y; da += x*x; db += y*y;
  }
  return num / Math.sqrt(da*db);
}

/* ===== render: física real por cuadro + vistas del resultado sellado ===== */
(function(){
  const cv=document.getElementById('cvQ'); const ctx=cv.getContext('2d');
  const P=KRAS.pts, E=KRAS.edges, n=KRAS.n;
  const isSrc=new Set(KRAS.src), isAllo=new Set(KRAS.allo);
  // la red real: coordenadas selladas + regla sellada (corte 8.5, sigma 6.0)
  const red = construirRed(KRAS.pts, {corte:8.5, sigma:6.0});
  let est = nuevoEstado(red, KRAS.src);
  const prob = new Float64Array(n);
  const DT=0.01, STEPS_PER_FRAME=5, T_END=8.0;
  let mode='live';
  const norm=(arr)=>{const lo=Math.min(...arr),hi=Math.max(...arr);return Array.from(arr,v=>(v-lo)/(hi-lo||1));};
  const sealed={ctqw:norm(KRAS.ctqw), diff:norm(KRAS.diff)};
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  let rect, ay=0.6, ax=0.35, dragging=false, lx=0, ly=0;
  const tval=document.getElementById('tval');
  function size(){const r=cv.getBoundingClientRect(),d=devicePixelRatio||1;cv.width=r.width*d;cv.height=r.height*d;ctx.setTransform(d,0,0,d,0,0);rect=r;}
  size();
  function proj(p){
    const cy=Math.cos(ay),sy=Math.sin(ay),cx=Math.cos(ax),sx=Math.sin(ax);
    let x=p[0]*cy+p[2]*sy, z=-p[0]*sy+p[2]*cy, y=p[1]*cx-z*sx; z=p[1]*sx+z*cx;
    const S=Math.min(rect.width,rect.height)/52;
    return [rect.width/2+x*S, rect.height/2+y*S, z];
  }
  function weights(){
    if(mode==='live'){ probabilidad(est, prob); return norm(prob); }
    return sealed[mode];
  }
  function draw(){
    ctx.clearRect(0,0,rect.width,rect.height);
    const Q=P.map(proj); const w=weights();
    ctx.lineWidth=1;
    for(const [a,b] of E){const A=Q[a],B=Q[b];const dz=(A[2]+B[2])/2;ctx.strokeStyle=`rgba(22,24,27,${0.05+0.09*(dz+23)/46})`;ctx.beginPath();ctx.moveTo(A[0],A[1]);ctx.lineTo(B[0],B[1]);ctx.stroke();}
    const order=[...Array(n).keys()].sort((i,j)=>Q[i][2]-Q[j][2]);
    for(const i of order){
      const [x,y,z]=Q[i]; const depth=(z+23)/46; const v=w[i];
      const r=1.4+v*4.2+depth*0.8;
      ctx.beginPath(); ctx.arc(x,y,r,0,7);
      ctx.fillStyle = v>0.08 ? `rgba(15,139,126,${0.18+0.82*v})` : `rgba(22,24,27,${0.16+0.25*depth})`;
      ctx.fill();
      if(isAllo.has(i)){ctx.beginPath();ctx.arc(x,y,r+3,0,7);ctx.strokeStyle='#0F8B7E';ctx.lineWidth=1.4;ctx.stroke();ctx.lineWidth=1;}
      if(isSrc.has(i)){ctx.beginPath();ctx.arc(x,y,r+1.6,0,7);ctx.strokeStyle='#16181B';ctx.lineWidth=1.1;ctx.stroke();ctx.lineWidth=1;}
    }
    if(tval) tval.textContent = mode==='live' ? est.t.toFixed(2) : 'sealed';
  }
  function loop(){
    if(mode==='live' && !reduced){ for(let k=0;k<STEPS_PER_FRAME;k++) paso(red, est, DT, false); if(est.t>=T_END) est=nuevoEstado(red, KRAS.src); }
    if(!dragging && !reduced) ay+=0.003;
    draw(); requestAnimationFrame(loop);
  }
  if(reduced){ for(let k=0;k<300;k++) paso(red, est, DT, false); draw(); } else { loop(); }
  const start=(x,y)=>{dragging=true;lx=x;ly=y;};
  const move=(x,y)=>{if(!dragging)return;ay+=(x-lx)*0.01;ax+=(y-ly)*0.01;lx=x;ly=y;if(reduced)draw();};
  cv.addEventListener('mousedown',e=>start(e.clientX,e.clientY));addEventListener('mousemove',e=>move(e.clientX,e.clientY));addEventListener('mouseup',()=>dragging=false);
  cv.addEventListener('touchstart',e=>{start(e.touches[0].clientX,e.touches[0].clientY);},{passive:true});
  cv.addEventListener('touchmove',e=>{move(e.touches[0].clientX,e.touches[0].clientY);},{passive:true});
  cv.addEventListener('touchend',()=>dragging=false);
  addEventListener('resize',()=>{size();if(reduced)draw();});
  document.querySelectorAll('.ftb').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.ftb').forEach(x=>x.classList.remove('on'));b.classList.add('on');mode=b.dataset.m; if(mode==='live') est=nuevoEstado(red, KRAS.src); if(reduced)draw();}));
})();
